-- =============================================================================
-- V496: Competence module — seed the four SKI 7.b requirements and their
--       2026-08 content.
--
-- GENERATED FILE. Produced from kompetencemodul_indhold_udvidet_2026-08.json
-- (the formatVersion-1 export) by scratchpad/gen_v496.py. Content edits after
-- go-live happen through the authoring UI and are versioned there, not by
-- editing this file.
--
-- Each topic gets one ACTIVE COURSE version and one ACTIVE TEST version at
-- version_label '2026-08'. Quiz answers are converted from the export's
-- [text, correct] tuples into options carrying stable, position-derived ids
-- (q1o1, q1o2, ...), because the submission protocol sends option ids and the
-- correct flag must never reach the client (spec §6.4).
--
-- 7.b.2 and 7.b.4 have no content yet and are created later through the
-- authoring UI — which is why "create a new requirement" is a first-class
-- feature rather than an admin afterthought.
-- =============================================================================

-- -------------------------------------------------------------------
-- Targeting: the Technology practice.
--
-- The canonical registry code is TECH. Never persist a practice by code —
-- resolve the uuid. If the row is missing, ABORT the migration rather than
-- seed a NULL target: all three target arrays NULL reads as noTargeting,
-- i.e. "everyone", which would put the entire company into mandatory
-- assessed training and start notifying them.
-- -------------------------------------------------------------------
SET @tech := (SELECT uuid FROM practice WHERE code = 'TECH' AND active = 1);

DELIMITER $$
CREATE PROCEDURE competence_seed_guard()
BEGIN
    IF @tech IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'V496: no active practice with code TECH — refusing to seed a NULL audience, which would target the whole company';
    END IF;
END$$
DELIMITER ;
CALL competence_seed_guard();
DROP PROCEDURE competence_seed_guard;

SET @target_practices := CONCAT('["', @tech, '"]');


