INSERT INTO competence_content_version
    (uuid, requirement_uuid, content_kind, version_label, status, payload_json,
     forced_retake, published_by, published_at, superseded_by_uuid,
     created_at, created_by, updated_at, modified_by)
VALUES ('40e0a919-59bc-52ea-b261-964d5d627fa3', @req, 'COURSE', '2026-08', 'ACTIVE',
        '{"screens":[{"role":"intro","title":"Sikker kodning","lede":"Genkend OWASP/CWE-mønstre i egen kode, vælg det rigtige forsvar, og indbyg sikkerhed fra start.","blocks":[{"type":"heading","text":"Læringsmål"},{"type":"list","ordered":false,"items":["Genkende OWASP/CWE-mønstre i egen kode og i review","Vælge rigtigt forsvar: parameterisering, kontekst-korrekt encoding, servervalidering","Håndtere autorisation, autentificering, kryptografi og datahåndtering forsvarligt","Genkende SSRF, usikker deserialisering og risikabel filhåndtering","Bruge open source ansvarligt: scanning, versionslåsning, opfølgning på fund","Vurdere og dokumentere ændringer i tredjeparts basiskode","Argumentere for security by design over for kunde og kollega"]},{"type":"paragraph","text":"10 afsnit · 1 video · ca. 18 min"}]},{"role":"content","title":"Trusselsmodel og tillidsgrænser","blocks":[{"type":"paragraph","text":"Alt der krydser en **tillidsgrænse** er fjendtligt indtil valideret. Input er meget mere end formularer: HTTP-headers, query-parametre, route-værdier, JSON- og XML-felter, cookies, filnavne, uploadet indhold, kø-beskeder, webhooks, svar fra andre API''er — og **data I selv har gemt tidligere**. Et felt der var validt da det blev gemt, er ikke nødvendigvis validt i den kontekst hvor det udskrives."},{"type":"paragraph","text":"Brug **STRIDE** som refleks når du designer: Spoofing (kan nogen udgive sig for en anden?), Tampering (kan data ændres undervejs?), Repudiation (kan en handling nægtes bagefter?), Information disclosure (læker vi noget?), Denial of service (kan det væltes?), Elevation of privilege (kan nogen få flere rettigheder end tildelt?)."},{"type":"paragraph","text":"Spørg tre ting ved hver ny endpoint: Hvem må kalde den? Hvilke data kommer ind, og hvor kommer de fra? Hvad er det værste der sker, hvis kalderen lyver om alt?"},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-04]** — hvornår laver vi trusselsmodellering i et projekt, hvem deltager, og hvilken skabelon bruger vi?"}]},{"role":"content","title":"Injection","blocks":[{"type":"paragraph","text":"Injection opstår når **kode og data blandes sammen**. Det gælder ikke kun SQL: også OS-kommandoer, LDAP-filtre, NoSQL-forespørgsler, XPath og dynamisk byggede filstier."},{"type":"paragraph","text":"Til databaser bruges **parameteriserede forespørgsler** — ikke manuel escaping, ikke egne \\"rens-funktioner\\". Et ORM er ikke automatisk sikkert: rå SQL genåbner risikoen, og strenginterpolation ind i rå SQL er lige så farligt som i ADO.NET."},{"type":"code","code":"// Usikker — brugerdata bygges ind i SQL-strengen\\nvar sql = \\"SELECT * FROM Users WHERE Id = \\" + userId;\\ndb.Query(sql);\\n\\n// Usikker — også i EF Core, hvis strengen interpoleres i forvejen\\nvar raw = $\\"SELECT * FROM Users WHERE Id = {userId}\\";\\ncontext.Users.FromSqlRaw(raw);\\n\\n// Sikker — parameter, ikke strengsammensætning\\ndb.Query(\\"SELECT * FROM Users WHERE Id = @id\\", new { id = userId });\\n\\n// Sikker — FromSqlInterpolated parameteriserer interpolationen\\ncontext.Users.FromSqlInterpolated($\\"SELECT * FROM Users WHERE Id = {userId}\\");"},{"type":"paragraph","text":"Ved OS-kommandoer: undgå at kalde en shell. Send argumenter som en liste til processen frem for at bygge én kommandolinje, og hold en **tillad-liste** over hvad der må kaldes."}]},{"role":"content","title":"XSS og output-encoding","blocks":[{"type":"paragraph","text":"Mod XSS gælder: **output-encode til den kontekst du udskriver i** — HTML-tekst, HTML-attribut, JavaScript, URL og CSS har hver sine regler. \\"Rens input ved indgangen\\" holder ikke, fordi den rigtige encoding afhænger af hvor data ender."},{"type":"paragraph","text":"Razor og Blazor encoder som standard, men `@Html.Raw(...)` og `MarkupString` slår beskyttelsen fra. I React gør `dangerouslySetInnerHTML` det samme. Bruger du dem, skal indholdet være saniteret af et anerkendt bibliotek — ikke af egne regulære udtryk."},{"type":"list","ordered":false,"items":["Pas på `innerHTML`, `outerHTML`, `document.write` og `eval`.","Pas på `href`, `src` og `formaction` der kan blive `javascript:` eller `data:`.","Sæt en **Content-Security-Policy** som ekstra lag — den erstatter ikke encoding, men begrænser skaden.","Cookies med sessionsdata sættes `HttpOnly`, `Secure` og `SameSite`."]}]},{"role":"content","title":"Adgangskontrol og autorisation","blocks":[{"type":"paragraph","text":"**Broken access control** er nummer ét på OWASP Top-10, og det er den fejltype vi oftest selv introducerer. **IDOR** (Insecure Direct Object Reference) opstår når en handling kun tjekker at brugeren er logget ind, men ikke at brugeren må røre netop den ressource."},{"type":"paragraph","text":"Autentificering ≠ autorisation. At skjule en knap i UI''et er ikke en kontrol — kaldet kan stadig sendes. Tjek altid **ejerskab og rettighed på serveren, pr. ressource**, og gør det ét sted frem for spredt ud i controllerne."},{"type":"code","code":"// Usikker — henter på id alene\\nvar invoice = await db.Invoices.FindAsync(id);\\nreturn Ok(invoice);\\n\\n// Sikker — ejerskab er en del af forespørgslen\\nvar invoice = await db.Invoices\\n    .SingleOrDefaultAsync(i => i.Id == id && i.CustomerId == currentUser.CustomerId);\\nif (invoice is null) return NotFound();   // ikke Forbid() — undgå at afsløre at id findes\\nreturn Ok(invoice);"},{"type":"paragraph","text":"Vælg **deny by default**: kræv autorisation globalt og gør undtagelserne eksplicitte, i stedet for at huske at beskytte hver ny endpoint."}]},{"role":"content","title":"Autentificering, sessioner og hemmeligheder i kode","blocks":[{"type":"paragraph","text":"Rul ikke din egen autentificering. Brug platformens — for os typisk **Entra ID / OpenID Connect** — og lad biblioteket validere token, signatur, udsteder, modtager og udløb. Egen JWT-validering er en klassisk kilde til fejl."},{"type":"list","ordered":false,"items":["**Password-hashing:** Argon2, bcrypt eller PBKDF2 med salt og passende arbejdsfaktor — aldrig ren SHA-256 eller MD5.","**Tokens og nøgler** hører i en secret-store, ikke i kode, konfiguration i repoet, eller kommentarer.","**Fejlbeskeder** skal være neutrale: \\"forkert brugernavn eller adgangskode\\", ikke \\"brugeren findes ikke\\".","**Rate limiting og lockout** på login og andre følsomme endpoints."]},{"type":"paragraph","text":"Under udvikling bruges `dotnet user-secrets` lokalt og en secret-store i miljøerne — så en hemmelighed aldrig behøver at ligge i en fil der kan committes."}]},{"role":"content","title":"Kryptografi og håndtering af data","blocks":[{"type":"paragraph","text":"Skriv ikke din egen krypto, og vælg ikke algoritmen selv hvis platformen har et højniveau-API. Brug TLS overalt, også internt mellem services, og krypter følsomme data i hvile."},{"type":"list","ordered":false,"items":["Kend forskellen: **hashing** (envejs, til verifikation), **kryptering** (tovejs, til fortrolighed), **signering** (til integritet og afsender).","Nøgler har en livscyklus: opbevaring, rotation, tilbagekaldelse. En nøgle uden rotationsplan er teknisk gæld.","**Dataminimering:** hent og gem kun det I skal bruge. Data I ikke har, kan ikke læke.","**Aldrig i logs:** adgangskoder, tokens, fulde kortnumre, CPR-numre, hele request-bodies med persondata."]},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-03]** — vores sikre defaults og kodestandard — hvilke krypto-API''er, log-regler og skabeloner bruger vi, og hvor findes standarden?"}]},{"role":"content","title":"SSRF, deserialisering og filhåndtering","blocks":[{"type":"list","ordered":false,"items":["**SSRF** — når serveren henter en URL brugeren har bestemt. Validér mod en tillad-liste, afvis private IP-intervaller og cloud-metadata-endpoints, og følg ikke redirects blindt.","**Usikker deserialisering** — undgå formater der kan instantiere vilkårlige typer på utroet input. Brug System.Text.Json med eksplicitte typer frem for polymorf deserialisering.","**Filupload** — validér filtype ud fra indhold og ikke kun endelse, generér nyt filnavn, gem uden for webroot, og servér aldrig uploadede filer fra samme origin som applikationen hvis de kan indeholde HTML.","**Path traversal** — sammensæt aldrig en sti med brugerinput uden at normalisere og kontrollere at resultatet stadig ligger inden for den tilladte mappe.","**XXE** — slå eksterne entiteter fra i XML-parsere."]}]},{"role":"content","title":"Open source og afhængigheder","blocks":[{"type":"paragraph","text":"Open source i en løsning til Kunden er **vores ansvar** — ikke tredjeparts. Kravet er ikke at undgå open source, men at kunne redegøre for hvad vi bruger, hvilken version, og at kendte sårbarheder bliver håndteret."},{"type":"list","ordered":true,"items":["**Versionslåsning:** commit lockfiles (`packages.lock.json`, `package-lock.json`) så builds er reproducerbare.","**Automatiseret scanning** i pipelinen, både af direkte og **transitive** afhængigheder — de fleste fund ligger et par lag nede.","**Opfølgning med ejer og frist:** et fund uden en ansvarlig er ikke håndteret.","**Vurdér nye pakker før de tages ind:** vedligeholdes den, hvor mange bruger den, hvor tæt er navnet på en kendt pakke (typosquatting), hvilken licens?","**Kunne svare på \\"hvad indeholder løsningen?\\"** — en afhængighedsliste eller SBOM pr. leverance."]},{"type":"paragraph","text":"Når en sårbarhed findes i en version I bruger: vurdér om den er reelt udnyttelig i jeres brug, opdatér til en rettet version hvis muligt, og afbød ellers risikoen eksplicit og dokumentér beslutningen. \\"Det er tredjeparts ansvar\\" er ikke et svar."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-01]** — hvilke sprog, frameworks og versioner er godkendte hos os, og findes der en liste over godkendte/forbudte pakker?"},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-02]** — hvordan scanner vi afhængigheder — hvilket værktøj, hvor i pipelinen, hvem følger op, og hvilken frist gælder for kritiske fund?"}]},{"role":"content","title":"Ændring af tredjeparts basiskode","blocks":[{"type":"paragraph","text":"Nogle gange er der pres for at rette direkte i en tredjepartspakkes basiskode — en fork, en patch, en overskrevet fil. Det må kun ske via en **dokumenteret tilpasningsproces**, og kun med **Kundens risikoaccept**, fordi tre risici følger med:"},{"type":"list","ordered":true,"items":["Leverandøren vil ikke længere **supportere** softwaren, fordi den er ændret.","Softwarens **indbyggede sikkerhedskontroller** virker måske ikke længere som forudsat.","Softwaren bliver **vanskelig at opdatere** — hver ny version skal patches igen, og sikkerhedsopdateringer bliver dyre eller udskydes."]},{"type":"paragraph","text":"Overvej altid alternativerne først: en konfigurationsmulighed, et udvidelsespunkt, en wrapper uden om pakken, et bidrag tilbage til projektet, eller et andet produkt. Vælger I alligevel at ændre basiskoden, skal ændringen isoleres, dokumenteres og kunne genanvendes ved næste opgradering."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-05]** — vores tilpasningsproces for tredjeparts basiskode — hvem beslutter, hvordan dokumenteres afvigelsen, og hvor indhentes og gemmes Kundens risikoaccept?"}]},{"role":"content","title":"Security by design and by default","blocks":[{"type":"paragraph","text":"**Security by design** betyder at sikkerhed indgår i arkitektur- og designbeslutninger fra starten, ikke som en gennemgang til sidst. **By default** betyder at den sikre indstilling er den man får uden at gøre noget."},{"type":"list","ordered":false,"items":["**Deny by default** — luk alt, åbn eksplicit det der skal være åbent.","**Mindste rettighed** — både for brugere, services, pipelines og databaseforbindelser.","**Fejl sikkert** — en undtagelse skal ikke ende med at give adgang eller afsløre interne detaljer.","**Forsvar i dybden** — antag at ét lag svigter, og sørg for at der er et lag mere.","**Gør det rigtige nemt** — en delt skabelon eller et internt bibliotek med sikre defaults slår en politik ingen læser."]},{"type":"paragraph","text":"For **blandede applikationer** — vores kode plus open source plus platformstjenester — gælder kravet om \\"sikker ved design\\" for **hele** sammensætningen. Det er ikke nok at vores egne linjer er i orden."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-06]** — hvem kontaktes, og hvad er de første skridt, hvis en udvikler opdager en sårbarhed eller mistænker en hændelse i en kundeløsning?"}]},{"role":"video","title":"Video","blocks":[{"type":"video","note":"[Udfyldes + godkendes inden ibrugtagning]"},{"type":"paragraph","text":"Supplerende læsning: OWASP Top 10 · OWASP Cheat Sheet Series (.NET Security, Input Validation, Authorization) · SANS/CWE Top 25 · Microsoft Learn — Secure coding guidelines for .NET"}]},{"role":"summary","title":"Opsummering","blocks":[{"type":"keypoints","items":["Tillidsgrænser: alt input er fjendtligt indtil valideret — også egne gemte data","Parameterisering mod injection, kontekst-korrekt encoding mod XSS","Autorisation tjekkes pr. ressource på serveren, deny by default","Brug platformens autentificering og krypto — skriv ikke din egen","SSRF, deserialisering, filupload og path traversal har kendte forsvar","Open source scannes, låses og følges op på — det er vores ansvar","Ændring af tredjeparts basiskode kræver proces og Kundens risikoaccept","Security by design gælder hele den blandede applikation"]}]}]}',
        1, 'system', NOW(6), NULL, NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), updated_at = NOW(6), modified_by = 'V496';

INSERT INTO competence_content_version
    (uuid, requirement_uuid, content_kind, version_label, status, payload_json,
