     created_at, created_by, updated_at, modified_by)
VALUES ('134e2ac9-b17c-5af9-9150-92fcb25ae7c8', @req, 'TEST', '2026-08', 'ACTIVE',
        '{"questions":[{"id":"q1","text":"En bruger-input skal vises på en webside. Hvad beskytter bedst mod XSS?","options":[{"id":"q1o1","text":"Output-encoding/escaping af data i den rette kontekst","correct":true},{"id":"q1o2","text":"Fjerne mellemrum fra input","correct":false},{"id":"q1o3","text":"Vise input med større skriftstørrelse","correct":false},{"id":"q1o4","text":"Logge alle inputs","correct":false}]},{"id":"q2","text":"Hvad er den sikreste måde at håndtere en database-forespørgsel med brugerdata?","options":[{"id":"q2o1","text":"Parameteriserede forespørgsler / prepared statements","correct":true},{"id":"q2o2","text":"Strengsammensætning med brugerdata","correct":false},{"id":"q2o3","text":"Skjule SQL i en kommentar","correct":false},{"id":"q2o4","text":"Køre forespørgslen som administrator","correct":false}]},{"id":"q3","text":"Et open source-bibliotek har en kendt sårbarhed i den version I bruger. Hvad gør du?","options":[{"id":"q3o1","text":"Vurderer og opdaterer til en rettet version, ellers afbøder risikoen","correct":true},{"id":"q3o2","text":"Ignorerer det, da det er tredjeparts ansvar","correct":false},{"id":"q3o3","text":"Fjerner versionsnummeret fra dokumentationen","correct":false},{"id":"q3o4","text":"Venter til en kunde klager","correct":false}]},{"id":"q4","text":"Hvornår bør validering af input ske?","options":[{"id":"q4o1","text":"På serversiden, uanset evt. klientvalidering","correct":true},{"id":"q4o2","text":"Kun i browseren, for hastighed","correct":false},{"id":"q4o3","text":"Kun hvis brugeren beder om det","correct":false},{"id":"q4o4","text":"Aldrig, hvis HTTPS er slået til","correct":false}]},{"id":"q5","text":"Hvad menes med ''sikker ved design'' for blandede applikationer?","options":[{"id":"q5o1","text":"Sikkerhed indtænkes fra start, også for de open source-dele der indgår","correct":true},{"id":"q5o2","text":"At appen ser professionel ud","correct":false},{"id":"q5o3","text":"At kildekoden er skjult for brugeren","correct":false},{"id":"q5o4","text":"At der kun bruges ét programmeringssprog","correct":false}]},{"id":"q6","text":"Et endpoint henter en faktura ud fra det id, kalderen sender, og brugeren er logget ind. Hvad mangler?","options":[{"id":"q6o1","text":"Et servertjek af om netop denne bruger må se netop den faktura","correct":true},{"id":"q6o2","text":"En hurtigere database-forespørgsel","correct":false},{"id":"q6o3","text":"At knappen skjules i brugerfladen for andre brugere","correct":false},{"id":"q6o4","text":"At id''et sendes som POST i stedet for GET","correct":false}]},{"id":"q7","text":"Hvordan bør adgangskoder gemmes?","options":[{"id":"q7o1","text":"Hashet med Argon2, bcrypt eller PBKDF2 med salt","correct":true},{"id":"q7o2","text":"Hashet med ren SHA-256 uden salt","correct":false},{"id":"q7o3","text":"Krypteret med en nøgle der ligger i kildekoden","correct":false},{"id":"q7o4","text":"I klartekst, hvis databasen er bag en firewall","correct":false}]},{"id":"q8","text":"En funktion henter indholdet af en URL, som brugeren selv angiver. Hvilken risiko er det primært?","options":[{"id":"q8o1","text":"SSRF — serveren kan narres til at kalde interne adresser og cloud-metadata","correct":true},{"id":"q8o2","text":"Cross-site scripting i brugerens browser","correct":false},{"id":"q8o3","text":"At siden bliver langsommere at indlæse","correct":false},{"id":"q8o4","text":"Ingen, så længe URL''en bruger HTTPS","correct":false}]},{"id":"q9","text":"Hvorfor committes lockfiles (fx packages.lock.json) til repoet?","options":[{"id":"q9o1","text":"For at builds bliver reproducerbare, så vi ved præcis hvilke versioner der indgår","correct":true},{"id":"q9o2","text":"For at gøre repoet mindre","correct":false},{"id":"q9o3","text":"For at skjule hvilke pakker vi bruger","correct":false},{"id":"q9o4","text":"Det er kun nødvendigt i frontend-projekter","correct":false}]},{"id":"q10","text":"I vil rette direkte i basiskoden på en tredjepartspakke i en kundeløsning. Hvad kræves?","options":[{"id":"q10o1","text":"En dokumenteret tilpasningsproces og Kundens risikoaccept, fordi support, indbyggede kontroller og fremtidige opdateringer påvirkes","correct":true},{"id":"q10o2","text":"Ingenting, så længe ændringen virker og er testet","correct":false},{"id":"q10o3","text":"Kun at ændringen kommenteres i koden","correct":false},{"id":"q10o4","text":"Kun at pakkens licens tillader ændringer","correct":false}]}]}',
        1, 'system', NOW(6), NULL, NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), updated_at = NOW(6), modified_by = 'V496';


