INSERT INTO competence_content_version
    (uuid, requirement_uuid, content_kind, version_label, status, payload_json,
     forced_retake, published_by, published_at, superseded_by_uuid,
     created_at, created_by, updated_at, modified_by)
VALUES ('0fd2de19-da14-5554-8cf2-77fb2c8f46d1', @req, 'COURSE', '2026-08', 'ACTIVE',
        '{"screens":[{"role":"intro","title":"Versionsstyring & kodeopbevaring","lede":"Git som sikkerhedskontrol, branch policies, review, hemmeligheder og sikker opbevaring af kildekode.","blocks":[{"type":"heading","text":"Læringsmål"},{"type":"list","ordered":false,"items":["Forklare versionsstyrings sikkerhedsegenskaber og hvorfor de er kontroller","Indrette branch policies så review og tjek er håndhævede, ikke aftalte","Lave code review der faktisk fanger sikkerhedsproblemer","Forebygge at hemmeligheder havner i repoet — og reagere korrekt når det sker","Forstå hvad sikker, adgangsstyret opbevaring af kildekode kræver","Indrette pipeline-identiteter efter mindste rettighed"]},{"type":"paragraph","text":"8 afsnit · 1 video · ca. 15 min"}]},{"role":"content","title":"Git som sikkerhedskontrol","blocks":[{"type":"paragraph","text":"Versionsstyring er ikke kun et samarbejdsværktøj. Det giver fire egenskaber vi kan pege på som kontroller over for en revisor:"},{"type":"list","ordered":false,"items":["**Sporbarhed** — hvem ændrede hvad, hvornår og hvorfor.","**Review** — ændringer kan kræves gennemset af en anden før de får virkning.","**Tilbagerulning** — en fejl eller et kompromis kan rulles tilbage til en kendt god tilstand.","**Integritet** — indholdet er hash-kædet, så historikken ikke kan ændres ubemærket."]},{"type":"paragraph","text":"**Signerede commits** hæver forfatteren fra \\"påstået\\" til \\"verificeret\\" — uden signering er navn og e-mail på en commit blot tekst, som enhver kan skrive."}]},{"role":"content","title":"Branch-strategi og branch policies","blocks":[{"type":"paragraph","text":"Arbejd i **kortlivede grene** og flet via pull request. Lange grene giver store, uoverskuelige diffs — og en diff ingen kan overskue bliver ikke reviewet reelt."},{"type":"paragraph","text":"**Branch policies** (Azure DevOps) / **branch protection** (GitHub) gør review og tjek obligatoriske. En håndhævet policy er en **kontrol**; en aftale om at man plejer at reviewe er det ikke."},{"type":"list","ordered":false,"items":["Kræv mindst én godkendelse — og overvej at forbyde at man godkender sin egen PR.","Kræv **build validation**: kompilering, tests og sikkerhedsscanning skal være grønne.","Kræv at kommentarer er løst før merge.","**Bloker direkte push og force-push** til beskyttede grene, også for administratorer.","Nulstil godkendelser når der pushes nye commits til PR''en.","Kræv tilknytning til et arbejdselement, så ændringen har en dokumenteret anledning."]},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-07]** — vores branch-strategi og navngivning, hvilke policies der konkret er slået til i Azure DevOps og GitHub, og hvem der administrerer dem."}]},{"role":"content","title":"Pull requesten som revisionsspor","blocks":[{"type":"paragraph","text":"En pull request er det sted hvor beslutningen om en ændring bliver dokumenteret. Efter merge skal man kunne læse ud af den: hvad blev ændret, hvorfor, hvem godkendte, og hvilke tjek var grønne."},{"type":"paragraph","text":"Derfor: skriv en beskrivelse der forklarer **hvorfor**, ikke kun hvad. Hold PR''en lille nok til at kunne læses. Og lad ikke godkendelsen være en formalitet — en godkendelse er en udtalelse om at du har set ændringen igennem."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-08]** — hvor mange reviewere kræver vi, hvem må godkende hvad, og er selv-godkendelse tilladt i nogen situationer?"}]},{"role":"content","title":"Code review med sikkerhedsøjne","blocks":[{"type":"paragraph","text":"Funktionalitet fanges ofte af tests. Sikkerhed fanges typisk kun af et menneske der ved hvad det skal lede efter. Led aktivt efter:"},{"type":"list","ordered":false,"items":["Manglende eller kun klient-side validering.","Strengbygget SQL, kommandoer eller stier.","**Hemmeligheder i diffen** — nøgler, tokens, forbindelsesstrenge, certifikater.","Manglende autorisationstjek på nye endpoints, især nye variationer af eksisterende.","PII eller hemmeligheder der logges, også indirekte via hele objekter.","Nye afhængigheder — og nye versioner af gamle.","Udkommenteret kode, `TODO`-noter om sikkerhed, og midlertidige omveje der aldrig blev fjernet.","Ændringer i konfiguration, pipelines og infrastruktur-som-kode — de reviewes ofte mindre grundigt end applikationskoden, men rammer hårdere."]}]},{"role":"content","title":"Hemmeligheder: forebyggelse","blocks":[{"type":"paragraph","text":"Den billigste hemmelighed at håndtere er den der aldrig kom ind i repoet. Rækkefølgen af forsvar:"},{"type":"list","ordered":true,"items":["**Ingen hemmeligheder i kode eller i konfigurationsfiler der committes.** Ikke i `appsettings.json`, ikke i en kommentar, ikke \\"midlertidigt\\".","**Lokalt:** `dotnet user-secrets` eller miljøvariabler, så filen der indeholder værdien ikke ligger i arbejdsmappen.","**I miljøerne:** en secret-store (fx Azure Key Vault), og hvor det er muligt **managed identity**, så der slet ikke er en hemmelighed at læke.","**`.gitignore`** for de filmønstre der typisk indeholder hemmeligheder — men betragt den som en hjælp, ikke en kontrol.","**Secret scanning med push protection**, så et forsøg stoppes før det bliver historik."]},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-09]** — hvor opbevarer vi hemmeligheder pr. miljø, hvem giver adgang til dem, og hvornår bruger vi managed identity frem for en nøgle?"},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-10]** — er secret scanning og push protection slået til på vores repositories, og hvem modtager alarmerne?"}]},{"role":"content","title":"Hemmeligheder: når det går galt","blocks":[{"type":"paragraph","text":"En slettet fil i en ny commit fjerner **ikke** hemmeligheden fra historikken — den ligger stadig i tidligere commits, i forks, i clones og i build-caches. Antag at værdien er kompromitteret i det øjeblik den blev pushet."},{"type":"paragraph","text":"Korrekt rækkefølge:"},{"type":"list","ordered":true,"items":["**Rotér** nøglen, så den gamle værdi bliver ugyldig — dette først, alt andet er sekundært.","Meld det til den ansvarlige, så det kan vurderes om der skal ske mere.","Rens historikken (`git filter-repo` eller BFG) og koordinér med alle der har et clone.","Flyt værdien til en secret-store, og skift til managed identity hvis det kan.","Slå secret scanning og push protection til, hvis det ikke allerede var det.","Se i logs om den lækkede nøgle blev brugt i mellemtiden."]},{"type":"paragraph","text":"At repoet er privat er ingen undskyldning. Private repos bliver delt, forket, klonet og en dag måske gjort offentlige."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-06]** — hvem kontaktes ved en lækket hemmelighed, og hvor registreres hændelsen? (samme kontaktvej som ved sårbarheder)"}]},{"role":"content","title":"Sikker opbevaring og adgangsstyring","blocks":[{"type":"paragraph","text":"Kildekode opbevares **centralt, adgangsstyret og logget** — ikke på en USB-nøgle, ikke som vedhæftet fil i en mail, ikke kun på en enkelt udviklers maskine, og ikke i et privat repo under en personlig konto."},{"type":"list","ordered":false,"items":["Adgang tildeles via **grupper og roller**, ikke person for person.","**Onboarding og offboarding** skal være en rutine: adgang fjernes samme dag en person stopper eller skifter opgave.","**Personal access tokens** har kort levetid, mindst muligt scope, og gennemgås jævnligt.","Adgangen **gennemgås periodisk** — hvem har adgang til hvilke repos, og er det stadig nødvendigt?","Ved projektafslutning: aftal og dokumentér hvad der sker med kodebasen og adgangen til den."]},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-11]** — hvordan er adgang til vores repositories organiseret i grupper, hvordan håndteres til- og fratrædelse, hvad er vores PAT-politik, og hvor ofte gennemgås adgangen?"}]},{"role":"content","title":"Pipeline- og build-sikkerhed","blocks":[{"type":"paragraph","text":"Pipelinen har ofte flere rettigheder end nogen enkelt udvikler — den kan deploye til produktion. Derfor er den et mål, og derfor gælder mindste rettighed også her."},{"type":"list","ordered":false,"items":["**Service connections og pipeline-identiteter** skal have præcis de rettigheder de skal bruge — ikke en bred administratorrolle — og de skal have en navngiven ejer.","Pipeline-definitioner er kode: de ligger i repoet og reviewes som alt andet.","Hemmeligheder maskeres i logs, og build-output gennemses for utilsigtet udskrivning.","Deployment til produktion sker gennem godkendelser eller gates, ikke ved at en udvikler trykker på en knap uden kontrol.","Byg fra en kendt kilde og verificér integriteten af det der deployes."]},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-12]** — hvilke service connections og pipeline-identiteter har vi, hvem ejer dem, hvilke rettigheder har de, og hvornår blev de sidst gennemgået?"}]},{"role":"video","title":"Video","blocks":[{"type":"video","note":"[Udfyldes + godkendes inden ibrugtagning]"},{"type":"paragraph","text":"Supplerende læsning: Microsoft Learn — Secure Azure Pipelines · Branch policies and settings i Azure Repos · Secret scanning og push protection · GitHub Docs — About protected branches"}]},{"role":"summary","title":"Opsummering","blocks":[{"type":"keypoints","items":["Fire sikkerhedsegenskaber: sporbarhed, review, tilbagerulning, integritet","Kortlivede grene, PR, og branch policies som håndhævet kontrol","PR''en er revisionssporet — beskrivelse, godkendelse og grønne tjek","Review er stedet hvor sikkerhedsfejl faktisk fanges","Hemmeligheder forebygges med secret-store, managed identity og push protection","Ved læk: rotér først, rens historik bagefter","Central, adgangsstyret og logget opbevaring — med offboarding der virker","Pipeline-identiteter har mindste rettighed og en navngiven ejer"]}]}]}',
        1, 'system', NOW(6), NULL, NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), updated_at = NOW(6), modified_by = 'V496';

INSERT INTO competence_content_version
    (uuid, requirement_uuid, content_kind, version_label, status, payload_json,
     forced_retake, published_by, published_at, superseded_by_uuid,
     created_at, created_by, updated_at, modified_by)
VALUES ('d6c7c2a2-a10a-5110-bf05-618359315d47', @req, 'TEST', '2026-08', 'ACTIVE',
        '{"questions":[{"id":"q1","text":"Hvorfor er branch protection på main-grenen relevant for sikker udvikling?","options":[{"id":"q1o1","text":"Det forhindrer ikke-reviewede ændringer i at nå produktionskoden","correct":true},{"id":"q1o2","text":"Det gør repositoriet hurtigere","correct":false},{"id":"q1o3","text":"Det skjuler commit-historikken","correct":false},{"id":"q1o4","text":"Det fjerner behovet for backup","correct":false}]},{"id":"q2","text":"En API-nøgle er ved en fejl committed til Git-historikken. Hvad er korrekt?","options":[{"id":"q2o1","text":"Nøglen roteres straks, og historikken renses","correct":true},{"id":"q2o2","text":"Man sletter kun den seneste commit","correct":false},{"id":"q2o3","text":"Man omdøber filen","correct":false},{"id":"q2o4","text":"Det er fint, hvis repoet er privat","correct":false}]},{"id":"q3","text":"Hvad kendetegner sikker opbevaring af kildekode?","options":[{"id":"q3o1","text":"Adgangsstyret, centraliseret repository med logning","correct":true},{"id":"q3o2","text":"Kode på en delt USB-nøgle","correct":false},{"id":"q3o3","text":"Kode i vedhæftede filer på e-mail","correct":false},{"id":"q3o4","text":"Kode på den enkelte udviklers skrivebord","correct":false}]},{"id":"q4","text":"Hvad er formålet med code review før merge?","options":[{"id":"q4o1","text":"At fange fejl og sikkerhedsproblemer før de når produktion","correct":true},{"id":"q4o2","text":"At forsinke leverancer","correct":false},{"id":"q4o3","text":"At tælle antal linjer kode","correct":false},{"id":"q4o4","text":"At undgå at skrive tests","correct":false}]},{"id":"q5","text":"Hvad er forskellen på en aftale og en kontrol i denne sammenhæng?","options":[{"id":"q5o1","text":"En kontrol er håndhævet af systemet, fx en branch policy, og kan ikke glemmes","correct":true},{"id":"q5o2","text":"Der er ingen praktisk forskel, så længe alle kender aftalen","correct":false},{"id":"q5o3","text":"En aftale er stærkere, fordi den er indgået mellem mennesker","correct":false},{"id":"q5o4","text":"En kontrol gælder kun for eksterne konsulenter","correct":false}]},{"id":"q6","text":"Hvilken af disse tilføjer mest sikkerhed, hvis den fjerner behovet for at have en hemmelighed overhovedet?","options":[{"id":"q6o1","text":"Managed identity, hvor tjenesten autentificerer sig uden en gemt nøgle","correct":true},{"id":"q6o2","text":"En længere adgangskode i appsettings.json","correct":false},{"id":"q6o3","text":"At lægge nøglen i en kommentar i stedet for i koden","correct":false},{"id":"q6o4","text":"At base64-kode nøglen før den committes","correct":false}]},{"id":"q7","text":"Hvorfor skal pipeline-definitioner og infrastruktur-som-kode reviewes lige så grundigt som applikationskode?","options":[{"id":"q7o1","text":"De kan ændre rettigheder og deploye til produktion, så en fejl her rammer hårdere","correct":true},{"id":"q7o2","text":"De påvirker kun byggetiden","correct":false},{"id":"q7o3","text":"Det er kun nødvendigt hvis de er skrevet i YAML","correct":false},{"id":"q7o4","text":"De behøver faktisk ikke reviewes, da de ikke er rigtig kode","correct":false}]},{"id":"q8","text":"Hvad er det vigtigste at gøre, når en medarbejder holder op eller skifter opgave?","options":[{"id":"q8o1","text":"Fjerne adgang til repositories og tokens som en fast del af rutinen","correct":true},{"id":"q8o2","text":"Slette personens gamle commits fra historikken","correct":false},{"id":"q8o3","text":"Omdøbe de grene personen har arbejdet i","correct":false},{"id":"q8o4","text":"Ingenting, adgangen udløber af sig selv","correct":false}]},{"id":"q9","text":"Hvad giver signerede commits ud over almindelige commits?","options":[{"id":"q9o1","text":"Verificeret forfatter i stedet for blot en påstået identitet","correct":true},{"id":"q9o2","text":"Kryptering af kildekoden i repoet","correct":false},{"id":"q9o3","text":"Automatisk sletning af hemmeligheder i diffen","correct":false},{"id":"q9o4","text":"Hurtigere merge af pull requests","correct":false}]},{"id":"q10","text":"Hvorfor er lange, langlivede grene et sikkerhedsproblem og ikke kun et arbejdsgeneproblem?","options":[{"id":"q10o1","text":"Store diffs bliver ikke reviewet reelt, så fejl og sikkerhedsproblemer glider igennem","correct":true},{"id":"q10o2","text":"De optager for meget plads i repositoriet","correct":false},{"id":"q10o3","text":"Git kan ikke beregne integritet på lange grene","correct":false},{"id":"q10o4","text":"De kan ikke beskyttes med branch policies","correct":false}]}]}',
        1, 'system', NOW(6), NULL, NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), updated_at = NOW(6), modified_by = 'V496';


