-- -------------------------------------------------------------------
INSERT INTO competence_requirement
    (uuid, comp_id, kref, name, description, target_practice_uuids,
     target_teams, target_useruuids, cadence_days_override, sort_order, active,
     created_at, created_by, updated_at, modified_by)
VALUES ('f4b274c8-3e28-5689-b454-b8504966b49f', 'metode', '7.b.6', 'Udviklingsmetodens syv punkter',
        'Miljøadskillelse, ingen følsomme data i kode, formel ændringsproces.', @target_practices,
        NULL, NULL, NULL, 2, 1,
        NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE
    kref        = VALUES(kref),
    name        = VALUES(name),
    description = VALUES(description),
    sort_order  = VALUES(sort_order),
    updated_at  = NOW(6),
    modified_by = 'V496';

-- Resolve the requirement by its stable comp_id rather than reusing the uuid
-- literal above: comp_id is the UNIQUE key, so if a row already existed under
-- a different uuid the INSERT above updated THAT row and the literal would
-- dangle on the FK below.
SET @req := (SELECT uuid FROM competence_requirement WHERE comp_id = 'metode');

INSERT INTO competence_content_version
    (uuid, requirement_uuid, content_kind, version_label, status, payload_json,
     forced_retake, published_by, published_at, superseded_by_uuid,
     created_at, created_by, updated_at, modified_by)
VALUES ('f0aeefd0-7471-5bb9-b04c-9127da020394', @req, 'COURSE', '2026-08', 'ACTIVE',
        '{"screens":[{"role":"intro","title":"Udviklingsmetodens syv punkter","lede":"Miljøadskillelse, kontrolleret adgang til drift, formel ændringsproces, og korrekt håndtering af data, kode og ændringer.","blocks":[{"type":"heading","text":"Læringsmål"},{"type":"list","ordered":false,"items":["Redegøre for de syv punkter og den risiko hvert punkt adresserer","Forklare hvorfor udvikling og test aldrig sker i driftsmiljøet","Forklare hvordan uautoriserede ændringer i drift forhindres teknisk","Håndtere følsomme data og hemmeligheder korrekt før ibrugtagning","Bruge central kodelagring og streng versionskontrol i praksis","Følge en formel, dokumenteret ændringsproces — også ved hastesager"]},{"type":"paragraph","text":"8 afsnit · 1 video · ca. 14 min"}]},{"role":"content","title":"De syv punkter i overblik","blocks":[{"type":"paragraph","text":"Kravet til vores udviklingsmetode består af syv punkter. De hænger sammen, men det er værd at kunne dem hver for sig, fordi de adresserer forskellige risici:"},{"type":"list","ordered":true,"items":["Kun udvikle i et **dedikeret udviklingsmiljø** — aldrig i driftsmiljøet.","**Forhindre** udviklingsmedarbejdere i at foretage uautoriserede ændringer i levende miljøer.","Kun teste i et **dedikeret testmiljø** — aldrig i driftsmiljøet.","**Fjerne unødvendige følsomme oplysninger** fra programmer før de implementeres i live-miljøet.","Anvende en **centraliseret metode** til lagring af kode.","Anvende **streng versionskontrol** over systemudviklingssoftware.","Udføre ændringer efter en **formel, dokumenteret proces**, så funktionalitet og sikkerhedskontroller ikke kompromitteres."]},{"type":"paragraph","text":"Det fælles princip bag dem: **adskil miljøer, kontrollér adgang, kontrollér ændringer, beskyt data og kode, og sikr sporbarhed.**"}]},{"role":"content","title":"Punkt 1: Dedikeret udviklingsmiljø","blocks":[{"type":"paragraph","text":"Udvikling foregår i et miljø der er adskilt fra drift — egen instans, egen database, egne hemmeligheder. Grunden er ikke ryddelighed, men at et udviklingsmiljø **er og skal være ustabilt**: der eksperimenteres, der fejler, der slås ting til og fra."},{"type":"paragraph","text":"Et udviklingsmiljø må derfor ikke kunne skrive til produktionsdata, og en forbindelsesstreng til produktion hører ikke i en udviklers konfiguration."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-13]** — hvilke miljøer har vi pr. kundeløsning, og hvordan er de adskilt i Azure — separate subscriptions, resource groups, netværk, databaser?"}]},{"role":"content","title":"Punkt 3: Dedikeret testmiljø og testdata","blocks":[{"type":"paragraph","text":"Test sker i et **separat testmiljø**, aldrig i drift. Testmiljøet skal ligne produktion i **opsætning** — samme platformversioner, samme konfiguration, samme sikkerhedsindstillinger — men ikke nødvendigvis i **rådata**."},{"type":"paragraph","text":"Produktionsdata kopieres ikke umaskeret til test. Persondata skal **anonymiseres eller pseudonymiseres** først, ellers har man i praksis udvidet produktionens beskyttelseskrav til et miljø hvor flere har adgang og hvor sikkerhedsniveauet er lavere."},{"type":"paragraph","text":"Det gælder også de nære genveje: en dump-fil på en udviklers maskine, et regneark med rigtige kunder til at teste importen, et skærmbillede med rigtige navne i en fejlrapport."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-15]** — hvor kommer vores testdata fra, hvilken anonymiseringsproces bruger vi, og hvem godkender at et datasæt må bruges i test?"}]},{"role":"content","title":"Punkt 2: Ingen uautoriserede ændringer i drift","blocks":[{"type":"paragraph","text":"Dette punkt er ikke en opfordring til at opføre sig ordentligt — det er et krav om at det **teknisk skal være forhindret**. En udvikler skal ikke kunne ændre i et levende miljø udenom processen, heller ikke velmenende."},{"type":"list","ordered":false,"items":["Almindelige udviklerkonti har **ikke** skriveadgang til produktion. Adgang til drift er en særskilt, begrænset rolle.","**Funktionsadskillelse:** den der udvikler ændringen, er ikke den der egenhændigt godkender og sætter den i drift.","Ændringer i drift sker **kun gennem pipelinen** — ikke ved manuelle indgreb, håndkørte scripts, eller redigering direkte i en produktionsdatabase.","Hvor der er behov for undtagelsesadgang, sker det som **tidsbegrænset, begrundet og logget** adgang (just-in-time), ikke som permanent tildeling.","Rettigheder i drift **gennemgås periodisk** — hvem har Owner, Contributor eller tilsvarende, og hvorfor?","Det gælder også ikke-menneskelige identiteter: service principals og pipeline-forbindelser skal have mindste rettighed og en ejer."]},{"type":"paragraph","text":"Bemærk at hvis en produktionsændring alligevel *kan* laves i hånden, så vil den blive lavet i hånden en travl fredag. Kontrollen er der for at beskytte den der har travlt."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-14]** — hvem har i dag skriveadgang til produktion pr. løsning, hvordan tildeles og fjernes den, har vi tidsbegrænset adgang (PIM/JIT), og hvor ofte gennemgås listen?"}]},{"role":"content","title":"Punkt 4: Fjern følsomme oplysninger før drift","blocks":[{"type":"paragraph","text":"Før kode sættes i drift, skal unødvendige følsomme oplysninger ud af den. Kravet nævner udtrykkeligt **godkendelsesoplysninger og krypterings-/API-nøgler i udviklernes kommentarer** — netop fordi det er der de gemmer sig."},{"type":"list","ordered":false,"items":["Hemmeligheder ud af kode, konfiguration **og kommentarer** — også udkommenterede.","Testbrugere, standardadgangskoder og bagdøre til lokal fejlsøgning fjernes eller slås fra.","Detaljerede fejlsider, debug-endpoints, Swagger-UI og verbose logging vurderes: skal de være tilgængelige i drift?","Eksempeldata og hårdkodede rigtige personoplysninger fjernes.","Verificér det med **automatiseret scanning** i pipelinen frem for hukommelse."]}]},{"role":"content","title":"Punkt 5 og 6: Central kode og streng versionskontrol","blocks":[{"type":"paragraph","text":"Al kode ligger i et **centralt, adgangsstyret repository** med logning — det er både kravet om centraliseret lagring og forudsætningen for alt det andet. Kode der kun findes lokalt kan ikke reviewes, ikke revideres og ikke gendannes."},{"type":"paragraph","text":"**Streng versionskontrol** betyder at det til enhver tid er klart **hvilken version der kører hvor**, hvad der er ændret siden sidst, og af hvem. Det er det der gør tilbagerulning og hændelsesundersøgelse mulig — uden det kan man ikke svare på \\"hvad kørte der, da fejlen skete?\\"."},{"type":"list","ordered":false,"items":["Releases er versionerede og kan identificeres — tags, build-numre, eller tilsvarende.","Der er en entydig sammenhæng fra det der kører i drift, tilbage til en commit.","Det gælder også konfiguration og infrastruktur-som-kode, ikke kun applikationskoden."]},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-18]** — hvordan kan vi se hvilken version der kører i et givent miljø lige nu, og hvordan versionerer og dokumenterer vi releases?"}]},{"role":"content","title":"Punkt 7: Formel, dokumenteret ændringsproces","blocks":[{"type":"paragraph","text":"Ændringer i drift sker efter en **formel, dokumenteret proces** — så de ikke påvirker den tilsigtede funktionalitet negativt eller kompromitterer sikkerhedskontrollerne. Processen skal give fire ting: en **beslutning**, en **vurdering**, et **spor**, og en **vej tilbage**."},{"type":"list","ordered":true,"items":["Hvad ændres, hvorfor, og hvilken risiko er vurderet?","Hvem har godkendt, og hvornår?","Hvordan er det testet før det gik i drift?","Hvordan ruller vi tilbage hvis det går galt, og hvem beslutter det?","Hvordan verificerede vi bagefter at det virkede som forventet?"]},{"type":"paragraph","text":"**Hastesager** er ikke undtaget — de har blot en anden rækkefølge. En hotfix må gerne gå hurtigere end en almindelig ændring, men den skal dokumenteres og godkendes bagefter, og den skal tilbage gennem den normale vej (også ind i main-grenen, så rettelsen ikke forsvinder ved næste release)."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-16]** — hvordan ser vores ændringsproces ud, hvor dokumenteres en ændring, hvem godkender, hvordan håndterer vi hotfix, og hvem beslutter en tilbagerulning?"},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-17]** — hvilke pipelines deployer til produktion, hvem må udløse dem, og hvilke godkendelser eller gates ligger foran?"}]},{"role":"video","title":"Video","blocks":[{"type":"video","note":"[Udfyldes + godkendes inden ibrugtagning]"},{"type":"paragraph","text":"Supplerende læsning: Microsoft — Security Development Lifecycle (SDL) Practices · Azure Well-Architected Framework — Securing a development lifecycle · Microsoft Learn — Environments and approvals i Azure Pipelines · Microsoft Entra Privileged Identity Management"}]},{"role":"summary","title":"Opsummering","blocks":[{"type":"keypoints","items":["Dedikerede miljøer — udvikling og test aldrig i drift","Produktionsdata anonymiseres før de bruges i test","Adgang til drift er teknisk begrænset, ikke kun aftalt","Funktionsadskillelse: udvikler og godkender er ikke samme person","Følsomme oplysninger og hemmeligheder ud af kode og kommentarer","Central, adgangsstyret kode og entydig sporbarhed fra drift til commit","Ændringer kun via formel proces — også hotfix, blot i anden rækkefølge"]}]}]}',
        1, 'system', NOW(6), NULL, NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), updated_at = NOW(6), modified_by = 'V496';

INSERT INTO competence_content_version
    (uuid, requirement_uuid, content_kind, version_label, status, payload_json,
     forced_retake, published_by, published_at, superseded_by_uuid,
     created_at, created_by, updated_at, modified_by)
VALUES ('7505c7fe-0c4d-521d-9657-edfae10e5355', @req, 'TEST', '2026-08', 'ACTIVE',
        '{"questions":[{"id":"q1","text":"Hvor må udvikling foregå ifølge metoden?","options":[{"id":"q1o1","text":"I et dedikeret udviklingsmiljø – aldrig direkte i driftsmiljøet","correct":true},{"id":"q1o2","text":"Direkte i driftsmiljøet hvis det haster","correct":false},{"id":"q1o3","text":"I et tilfældigt miljø der er ledigt","correct":false},{"id":"q1o4","text":"På kundens egne servere uden aftale","correct":false}]},{"id":"q2","text":"Hvad skal ske med følsomme oplysninger (fx nøgler) før kode sættes i drift?","options":[{"id":"q2o1","text":"De fjernes fra koden og kommentarer","correct":true},{"id":"q2o2","text":"De flyttes til en kommentar nederst","correct":false},{"id":"q2o3","text":"De krypteres i en README","correct":false},{"id":"q2o4","text":"De efterlades, hvis koden er privat","correct":false}]},{"id":"q3","text":"Hvordan skal ændringer af systemer udføres?","options":[{"id":"q3o1","text":"Efter en formel, dokumenteret ændringsproces","correct":true},{"id":"q3o2","text":"Når som helst, uden dokumentation","correct":false},{"id":"q3o3","text":"Kun mundtligt aftalt","correct":false},{"id":"q3o4","text":"Af den der har tid","correct":false}]},{"id":"q4","text":"Hvor må test af ny funktionalitet ske?","options":[{"id":"q4o1","text":"I et dedikeret testmiljø – aldrig i driftsmiljøet","correct":true},{"id":"q4o2","text":"I driftsmiljøet uden for arbejdstid","correct":false},{"id":"q4o3","text":"Direkte hos kunden","correct":false},{"id":"q4o4","text":"Det er ligegyldigt hvor","correct":false}]},{"id":"q5","text":"Metoden kræver at udviklere forhindres i at lave uautoriserede ændringer i drift. Hvad opfylder kravet?","options":[{"id":"q5o1","text":"At almindelige udviklerkonti teknisk ikke har skriveadgang til produktion","correct":true},{"id":"q5o2","text":"At alle har lovet ikke at ændre noget i produktion","correct":false},{"id":"q5o3","text":"At ændringer i produktion skrives ind i en logbog bagefter","correct":false},{"id":"q5o4","text":"At kun seniorudviklere ændrer i produktion","correct":false}]},{"id":"q6","text":"Hvorfor må produktionsdata ikke kopieres umaskeret til testmiljøet?","options":[{"id":"q6o1","text":"Fordi produktionens beskyttelseskrav så gælder et miljø med bredere adgang og lavere sikkerhedsniveau","correct":true},{"id":"q6o2","text":"Fordi testmiljøet ikke har plads nok","correct":false},{"id":"q6o3","text":"Fordi data bliver forældede","correct":false},{"id":"q6o4","text":"Det må man gerne, hvis man sletter dem bagefter","correct":false}]},{"id":"q7","text":"Hvad betyder funktionsadskillelse i forbindelse med ændringer i drift?","options":[{"id":"q7o1","text":"At den der udvikler en ændring, ikke egenhændigt godkender og sætter den i drift","correct":true},{"id":"q7o2","text":"At frontend og backend udvikles af forskellige personer","correct":false},{"id":"q7o3","text":"At test og udvikling foregår i forskellige uger","correct":false},{"id":"q7o4","text":"At kunden godkender al kode inden merge","correct":false}]},{"id":"q8","text":"En kritisk fejl i drift kræver en hotfix nu. Hvad er korrekt?","options":[{"id":"q8o1","text":"Hotfixet må gå hurtigere, men skal dokumenteres, godkendes og føres tilbage i den normale gren","correct":true},{"id":"q8o2","text":"Hastesager er undtaget fra ændringsprocessen","correct":false},{"id":"q8o3","text":"Rettelsen laves direkte i produktionsmiljøet og efterlades der","correct":false},{"id":"q8o4","text":"Man venter til næste planlagte release","correct":false}]},{"id":"q9","text":"Hvorfor er streng versionskontrol en forudsætning for at undersøge en hændelse?","options":[{"id":"q9o1","text":"Fordi man skal kunne svare på præcis hvilken version der kørte, hvad der var ændret, og af hvem","correct":true},{"id":"q9o2","text":"Fordi versionsnumre gør koden hurtigere","correct":false},{"id":"q9o3","text":"Fordi revisor kræver at der er mange commits","correct":false},{"id":"q9o4","text":"Fordi det erstatter behovet for logning","correct":false}]},{"id":"q10","text":"Der er brug for undtagelsesvis adgang til produktion for at fejlsøge. Hvad er den rigtige form?","options":[{"id":"q10o1","text":"Tidsbegrænset, begrundet og logget adgang, der falder væk af sig selv","correct":true},{"id":"q10o2","text":"Permanent adgang til den der oftest fejlsøger","correct":false},{"id":"q10o3","text":"En delt administratorkonto som teamet kender koden til","correct":false},{"id":"q10o4","text":"Adgang uden logning, så fejlsøgningen ikke støjer i loggen","correct":false}]}]}',
        1, 'system', NOW(6), NULL, NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), updated_at = NOW(6), modified_by = 'V496';


-- -------------------------------------------------------------------
-- 7.b.1 — Kendskab til udviklingsmetoden
--   12 course screens, 10 questions
-- -------------------------------------------------------------------
INSERT INTO competence_requirement
    (uuid, comp_id, kref, name, description, target_practice_uuids,
     target_teams, target_useruuids, cadence_days_override, sort_order, active,
     created_at, created_by, updated_at, modified_by)
VALUES ('f55c91c1-faac-5b96-953c-375cf8da584b', 'metode-kendskab', '7.b.1', 'Kendskab til udviklingsmetoden',
        'OWASP Top-10, SANS/CWE Top-25, security by design, logning og overvågning.', @target_practices,
        NULL, NULL, NULL, 3, 1,
        NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE
    kref        = VALUES(kref),
    name        = VALUES(name),
    description = VALUES(description),
    sort_order  = VALUES(sort_order),
    updated_at  = NOW(6),
    modified_by = 'V496';

-- Resolve the requirement by its stable comp_id rather than reusing the uuid
-- literal above: comp_id is the UNIQUE key, so if a row already existed under
-- a different uuid the INSERT above updated THAT row and the literal would
-- dangle on the FK below.
SET @req := (SELECT uuid FROM competence_requirement WHERE comp_id = 'metode-kendskab');

INSERT INTO competence_content_version
    (uuid, requirement_uuid, content_kind, version_label, status, payload_json,
     forced_retake, published_by, published_at, superseded_by_uuid,
     created_at, created_by, updated_at, modified_by)
VALUES ('09a377b5-2594-5b33-a478-64c1b9d826c6', @req, 'COURSE', '2026-08', 'ACTIVE',
        '{"screens":[{"role":"intro","title":"Kendskab til udviklingsmetoden","lede":"Metodens seks elementer: sikre programmeringsteknikker, god kodningspraksis, sikkerhedsarkitektur, sikker kodevejledning, indbygget sikkerhed, samt logning og overvågning.","blocks":[{"type":"heading","text":"Læringsmål"},{"type":"list","ordered":false,"items":["Kende de seks elementer i den dokumenterede udviklingsmetode","Forklare hvad godkendte, sikre programmeringsteknikker og god kodningspraksis dækker","Redegøre for principper for sikkerhedsarkitektur og applikationssikkerhed","Bruge OWASP Top-10 og SANS/CWE Top-25 som kodevejledning","Forklare \\"security by design and by default\\"","Forklare formålet med logning og overvågning — og hvad der aldrig må logges","Vide hvordan metoden holdes ajour, og hvad det betyder for dig"]},{"type":"paragraph","text":"9 afsnit · 1 video · ca. 15 min"}]},{"role":"content","title":"Hvad er udviklingsmetoden, og hvorfor er det et krav","blocks":[{"type":"paragraph","text":"Når vi udvikler eller konfigurerer på en kundes kritiske systemer, er det ikke nok at vi hver især gør vores bedste. Kunden skal kunne få bekræftet at vi **arbejder efter en dokumenteret metode**, at vi er **trænet i den**, og at vi **anvender den** i praksis."},{"type":"paragraph","text":"Metoden består af seks elementer: godkendte, sikre programmeringsteknikker; god kodningspraksis; principper for sikkerhedsarkitektur og applikationssikkerhed; sikker kodevejledning som OWASP Top-10 og SANS/CWE Top-25; principper om indbygget sikkerhed; samt logning og overvågning."},{"type":"paragraph","text":"Dette mikrokursus giver overblikket og sproget. De konkrete teknikker ligger i mikrokurserne om **sikker kodning**, **versionsstyring** og **udviklingsmetodens syv punkter**."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-19]** — hvor findes selve den dokumenterede udviklingsmetode — link eller placering — og hvem ejer den?"}]},{"role":"content","title":"Godkendte, sikre programmeringsteknikker","blocks":[{"type":"paragraph","text":"\\"Godkendte\\" betyder at teknikvalget ikke er den enkelte udviklers frie skøn. Der er et sæt sprog, frameworks, versioner og biblioteker vi arbejder i, og der er teknikker vi bruger frem for andre — fordi de er gennemtestede og fordi de er lettere at reviewe."},{"type":"list","ordered":false,"items":["Brug **anerkendte, vedligeholdte biblioteker** til sikkerhedskritiske opgaver — autentificering, krypto, sanitering — frem for egne løsninger.","Brug **platformens indbyggede mekanismer** frem for at bygge dem selv.","Hold jer på **understøttede versioner** af sprog, framework og runtime. En version uden sikkerhedsopdateringer er en sårbarhed der venter.","Vælg det **sikre standardmønster** når der er flere måder at gøre noget på."]},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-01]** — hvilke sprog, frameworks og versioner er godkendte hos os? (samme liste som i mikrokurset om sikker kodning)"}]},{"role":"content","title":"God kodningspraksis","blocks":[{"type":"paragraph","text":"God kodningspraksis er ikke kosmetik. Kode der er let at læse, er kode hvor en reviewer kan se en sikkerhedsfejl — og det er reviewet der fanger dem."},{"type":"list","ordered":false,"items":["Konsistent navngivning og struktur, så det er tydeligt hvad koden gør.","Klare grænser mellem lag, så det er tydeligt hvor validering og autorisation hører til.","Små, forståelige enheder frem for lange metoder med mange ansvar.","Automatiserede tests, så en senere ændring ikke stille slår en kontrol fra.","Statisk analyse og linting i pipelinen frem for i hukommelsen.","Genbrug af gennemtestede byggeklodser frem for at genopfinde løsninger."]},{"type":"paragraph","text":"Kort kode er ikke et mål i sig selv, og fravær af kommentarer er ikke et kvalitetstegn. Målet er kode hvor **intentionen er synlig**."}]},{"role":"content","title":"Sikkerhedsarkitektur og applikationssikkerhed","blocks":[{"type":"paragraph","text":"Nogle sikkerhedsproblemer kan ikke rettes i en enkelt metode — de er besluttet i arkitekturen. Derfor er principper for sikkerhedsarkitektur en del af metoden."},{"type":"list","ordered":false,"items":["**Tillidsgrænser** — hvor skifter data fra utroet til troet, og hvem validerer på den grænse?","**Forsvar i dybden** — antag at ét lag svigter, og hav et lag mere bagved.","**Segmentering og isolation** — komponenter, netværk og miljøer adskilles, så et brud ikke bliver totalt.","**Mindste rettighed** — for brugere, for services, for databaseforbindelser og for pipelines.","**Centraliseret håndhævelse** — autentificering og autorisation ét sted frem for gentaget i hver controller.","**Sikker fejltilstand** — når noget går galt, lukkes der ned, ikke op.","**Angrebsfladen holdes lille** — hvert ekstra endpoint, hver ekstra integration og hver offentlig IP er noget der skal forsvares."]},{"type":"paragraph","text":"Arkitekturbeslutninger er også de billigste at ændre tidligt. En manglende tillidsgrænse fundet i design koster en samtale; fundet i drift koster en release."}]},{"role":"content","title":"Sikker kodevejledning: OWASP Top-10","blocks":[{"type":"paragraph","text":"**OWASP Top-10** er en jævnligt opdateret liste over de mest kritiske risici i webapplikationer. Den er ikke en checkliste man består, men en **fælles referenceramme**: den giver os et sprog til at prioritere sikkerhedsarbejde og til at strukturere code review."},{"type":"paragraph","text":"Kategorierne dækker blandt andet: brudt adgangskontrol, kryptografiske fejl, injection, usikkert design, sikkerhedsmæssig fejlkonfiguration, sårbare og forældede komponenter, fejl i identifikation og autentificering, fejl i software- og dataintegritet, mangelfuld logning og overvågning, samt server-side request forgery."},{"type":"paragraph","text":"Brug den konkret: når du åbner en pull request, så løb kategorierne igennem mod netop den ændring. De fleste ændringer rører kun to eller tre af dem — men de to eller tre er værd at tænke over."}]},{"role":"content","title":"Sikker kodevejledning: SANS/CWE Top-25","blocks":[{"type":"paragraph","text":"**CWE** (Common Weakness Enumeration) er et katalog over konkrete svaghedstyper i software, og **SANS/CWE Top-25** er listen over de 25 mest udbredte og farlige af dem. Hvor OWASP Top-10 er organiseret efter risikokategori på applikationsniveau, er CWE tættere på **den konkrete fejl i koden** — hver svaghed har et id, fx CWE-89 for SQL injection eller CWE-79 for cross-site scripting."},{"type":"paragraph","text":"Derfor supplerer de to hinanden: OWASP giver overblik og prioritering, CWE giver præcision. Scanningsværktøjer og sårbarhedsrapporter refererer typisk til CWE-id''er, så det er værd at kunne læse dem."},{"type":"paragraph","text":"Genkendelige mønstre fra Top-25 i vores type løsninger: manglende inputvalidering, injection, cross-site scripting, brudt autorisation, hårdkodede legitimationsoplysninger, usikker deserialisering, path traversal, forkert håndtering af følsomme data i logs, og brug af komponenter med kendte sårbarheder."}]},{"role":"content","title":"Security by design and by default","blocks":[{"type":"paragraph","text":"Sikkerhed **indtænkes fra start** af arkitektur og kode — ikke som en gennemgang til sidst, hvor det både er dyrere at rette og for sent til at ændre designet."},{"type":"paragraph","text":"**By default** betyder at de sikre indstillinger er de indstillinger man får uden at gøre noget: **deny by default**, mindste rettighed, kryptering slået til, og ingen forventning om at brugeren eller den næste udvikler selv aktiverer beskyttelsen."},{"type":"paragraph","text":"Det har en praktisk konsekvens for os: den bedste måde at få security by design er at gøre det sikre valg til det **nemmeste** valg — delte skabeloner, interne biblioteker med sikre defaults, og pipelines hvor tjekkene allerede ligger."}]},{"role":"content","title":"Logning og overvågning","blocks":[{"type":"paragraph","text":"Logning og overvågning er en del af metoden, fordi det er det der gør det muligt at **opdage og undersøge hændelser**. Uden det ved man hverken at noget skete, eller hvad der skete."},{"type":"paragraph","text":"Log de sikkerhedsrelevante begivenheder: autentificering der lykkes og fejler, autorisationsafvisninger, ændringer i rettigheder, ændringer i konfiguration, adgang til følsomme data, og administrative handlinger. Sørg for at en hændelse kan følges på tværs af komponenter — samme korrelations-id gennem kæden."},{"type":"list","ordered":false,"items":["**Log aldrig:** adgangskoder, tokens, nøgler, hele request-bodies med persondata, CPR-numre, kortnumre.","En log er ikke kun til fejlsøgning — den kan være **bevismateriale**, og derfor skal den kunne stoles på: tidsstempler, integritet, og en opbevaringsperiode.","**Alarmer er der hvor logningen bliver til overvågning.** En log ingen ser på, opdager ingenting.","Overvågning er ikke kun teknisk oppetid — det er også usædvanlige mønstre: mange fejllogin, adgang på skæve tidspunkter, pludselige datamængder ud af systemet."]},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-21]** — hvilke værktøjer bruger vi til logning og overvågning (fx Application Insights, Log Analytics), hvad logges pr. løsning, hvor længe gemmes det, hvilke alarmer findes, og hvem reagerer på dem?"}]},{"role":"content","title":"Metoden holdes ajour — og hvad det betyder for dig","blocks":[{"type":"paragraph","text":"En dokumenteret metode må ikke blive et dokument der står stille. Kravet er at den **opdateres med nye tiltag og ny praksis** inden for fire områder: udviklingsteknikker inden for programmering, leveringsmetoder til applikationer (fx Cloud), applikationsarkitektur, og sikkerhedsstandarder og -teknikker."},{"type":"paragraph","text":"Konkret betyder det at metoden — og dette modul — har en **ejer**, en **kadence** for gennemgang, og en dokumenteret **beslutning** hver gang der ændres noget. Når indholdet får en ny version, skal du tage mikrokurset og testen igen; det er ikke en mistillid til din viden, men den måde vi kan vise at alle arbejder efter den **gældende** metode og ikke en tre år gammel udgave."},{"type":"paragraph","text":"Du er også selv en kilde: møder du en ny teknik, et nyt værktøj eller en praksis fra et kundeprojekt, som burde ind i metoden, så sig til frem for at holde det i eget projekt."},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-20]** — hvem ejer udviklingsmetoden og dette modul, hvor ofte gennemgås de, hvilke kilder følger vi for de fire områder, og hvor dokumenteres beslutningen om en opdatering?"},{"type":"callout","text":"**[Udfyldes af Trustworks · TW-22]** — hvornår i onboardingen skal en ny udvikler have gennemført modulet, hvad gælder for eksterne konsulenter, og hvem følger op på manglende gennemførelse?"}]},{"role":"video","title":"Video","blocks":[{"type":"video","note":"[Udfyldes + godkendes inden ibrugtagning]"},{"type":"paragraph","text":"Supplerende læsning: OWASP Top 10 · CWE Top 25 Most Dangerous Software Weaknesses · Microsoft — Security Development Lifecycle (SDL) Practices · OWASP Application Security Verification Standard (ASVS) · OWASP Logging Cheat Sheet"}]},{"role":"summary","title":"Opsummering","blocks":[{"type":"keypoints","items":["Metoden har seks elementer — og kravet er både at kende og anvende den","Godkendte teknikker: understøttede versioner, anerkendte biblioteker, platformens mekanismer","God kodningspraksis gør sikkerhedsfejl synlige for en reviewer","Sikkerhedsarkitektur: tillidsgrænser, dybde, segmentering, mindste rettighed","OWASP Top-10 giver overblik, SANS/CWE Top-25 giver præcision","Security by design and by default — det sikre valg skal være det nemmeste","Logning gør hændelser opdagelige; alarmer gør logning til overvågning","Metoden ajourføres med ejer og kadence — ny version betyder ny gennemførelse"]}]}]}',
        1, 'system', NOW(6), NULL, NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), updated_at = NOW(6), modified_by = 'V496';

INSERT INTO competence_content_version
    (uuid, requirement_uuid, content_kind, version_label, status, payload_json,
     forced_retake, published_by, published_at, superseded_by_uuid,
     created_at, created_by, updated_at, modified_by)
VALUES ('8f17cf7e-9664-561e-99f8-4cbc83fd8917', @req, 'TEST', '2026-08', 'ACTIVE',
        '{"questions":[{"id":"q1","text":"Hvad er OWASP Top-10?","options":[{"id":"q1o1","text":"En liste over de mest kritiske websikkerhedsrisici","correct":true},{"id":"q1o2","text":"En programmeringsstandard for skrifttyper","correct":false},{"id":"q1o3","text":"Et versionsstyringssystem","correct":false},{"id":"q1o4","text":"En cloud-leverandør","correct":false}]},{"id":"q2","text":"Hvad betyder ''security by design and by default''?","options":[{"id":"q2o1","text":"Sikkerhed er indbygget fra start og slået til som standard","correct":true},{"id":"q2o2","text":"Sikkerhed tilføjes til sidst hvis der er tid","correct":false},{"id":"q2o3","text":"Brugeren skal selv slå sikkerhed til","correct":false},{"id":"q2o4","text":"Sikkerhed er kun designernes ansvar","correct":false}]},{"id":"q3","text":"Hvorfor indgår logning og overvågning i metoden?","options":[{"id":"q3o1","text":"For at kunne opdage og undersøge hændelser","correct":true},{"id":"q3o2","text":"For at fylde diskplads","correct":false},{"id":"q3o3","text":"Det er kun et lovkrav uden praktisk værdi","correct":false},{"id":"q3o4","text":"For at gøre systemet langsommere","correct":false}]},{"id":"q4","text":"Hvad dækker ''god kodningspraksis'' blandt andet?","options":[{"id":"q4o1","text":"Anerkendte, sikre programmeringsteknikker og -principper","correct":true},{"id":"q4o2","text":"At skrive så kort kode som muligt","correct":false},{"id":"q4o3","text":"At undgå kommentarer","correct":false},{"id":"q4o4","text":"At bruge nyeste sprog uanset egnethed","correct":false}]},{"id":"q5","text":"Hvad er SANS/CWE Top-25, og hvordan forholder den sig til OWASP Top-10?","options":[{"id":"q5o1","text":"Et katalog over de 25 mest udbredte konkrete svaghedstyper i kode — mere præcist end OWASP, som giver overblik og prioritering","correct":true},{"id":"q5o2","text":"Den samme liste som OWASP Top-10, blot med 25 punkter","correct":false},{"id":"q5o3","text":"En liste over godkendte programmeringssprog","correct":false},{"id":"q5o4","text":"En standard for hvordan kildekode formateres","correct":false}]},{"id":"q6","text":"Hvilket af disse er et princip for sikkerhedsarkitektur?","options":[{"id":"q6o1","text":"Forsvar i dybden — antag at ét lag svigter, og hav et lag mere bagved","correct":true},{"id":"q6o2","text":"At al kode ligger i én fil, så den er nem at overskue","correct":false},{"id":"q6o3","text":"At sikkerhed vurderes ved projektets afslutning","correct":false},{"id":"q6o4","text":"At kildekoden holdes skjult, så angribere ikke kan læse den","correct":false}]},{"id":"q7","text":"Hvilken oplysning må aldrig ende i en applikationslog?","options":[{"id":"q7o1","text":"Adgangskoder, tokens og nøgler","correct":true},{"id":"q7o2","text":"Tidsstempel for hændelsen","correct":false},{"id":"q7o3","text":"Korrelations-id på tværs af komponenter","correct":false},{"id":"q7o4","text":"At et autorisationstjek afviste et kald","correct":false}]},{"id":"q8","text":"Hvorfor er en log med sikkerhedshændelser mere end et fejlsøgningsværktøj?","options":[{"id":"q8o1","text":"Den kan være bevismateriale, og skal derfor kunne stoles på — tidsstempler, integritet, opbevaringsperiode","correct":true},{"id":"q8o2","text":"Fordi den bruges til at måle applikationens ydeevne","correct":false},{"id":"q8o3","text":"Fordi den erstatter behovet for tests","correct":false},{"id":"q8o4","text":"Fordi den gør det muligt at slette data på anmodning","correct":false}]},{"id":"q9","text":"Kravet er at udviklingsmetoden holdes opdateret. Hvad dækker det blandt andet?","options":[{"id":"q9o1","text":"Nye udviklingsteknikker, leveringsmetoder som Cloud, applikationsarkitektur, samt sikkerhedsstandarder og -teknikker","correct":true},{"id":"q9o2","text":"Kun at rette stavefejl i dokumentet én gang om året","correct":false},{"id":"q9o3","text":"Kun de sprog vi aktuelt bruger i kundeprojekter","correct":false},{"id":"q9o4","text":"Kun ændringer som kunden udtrykkeligt beder om","correct":false}]},{"id":"q10","text":"Mikrokurset for et emne får en ny version. Hvad sker der for dig, og hvorfor?","options":[{"id":"q10o1","text":"Du skal gennemføre kursus og test igen, så det kan dokumenteres at alle arbejder efter den gældende metode","correct":true},{"id":"q10o2","text":"Ingenting — en tidligere bestået test gælder altid","correct":false},{"id":"q10o3","text":"Du skal kun tage testen igen, hvis du selv mener indholdet er ændret væsentligt","correct":false},{"id":"q10o4","text":"Din tidligere registrering slettes uden erstatning","correct":false}]}]}',
        1, 'system', NOW(6), NULL, NOW(6), 'V496', NOW(6), 'V496')
ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), updated_at = NOW(6), modified_by = 'V496';
